class Solution {
public:
    int findLonelyPixel(vector<vector<char>>& picture) {
        int m = picture.size(), n = picture[0].size();
        vector<int> rows(m, 0), cols(n, 0);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (picture[r][c] == 'B') {
                    ++rows[r];
                    ++cols[c];
                }
            }
        }
        int answer = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (picture[r][c] == 'B' && rows[r] == 1 && cols[c] == 1) {
                    ++answer;
                }
            }
        }
        return answer;
    }
};
